use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
    found: bool,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut t = self.root
        while t >= 0 {
            let k = self.keys[t]
            if x == k {
                return true
            }
            if x < k {
                t = self.lefts[t]
            } else {
                t = self.rights[t]
            }
        }
        false
    }

    fn add(self, x: int) -> int {
        self.keys.push(x)
        self.lefts.push(-1)
        self.rights.push(-1)
        let n: int = self.keys.len() as int
        n - 1
    }

    fn insert(self, x: int) {
        let n = self.add(x)
        if self.root < 0 {
            self.root = n
            return
        }
        let mut t = self.root
        loop {
            if x < self.keys[t] {
                if self.lefts[t] < 0 {
                    self.lefts[t] = n
                    return
                }
                t = self.lefts[t]
            } else {
                if self.rights[t] < 0 {
                    self.rights[t] = n
                    return
                }
                t = self.rights[t]
            }
        }
    }

    fn min_of(self, t0: int) -> int {
        let mut t = t0
        while self.lefts[t] >= 0 {
            t = self.lefts[t]
        }
        self.keys[t]
    }

    fn del(self, t: int, x: int) -> int {
        if t < 0 {
            return -1
        }
        let k = self.keys[t]
        if x < k {
            let l = self.del(self.lefts[t], x)
            self.lefts[t] = l
            return t
        }
        if x > k {
            let r = self.del(self.rights[t], x)
            self.rights[t] = r
            return t
        }
        self.found = true
        let l = self.lefts[t]
        let r = self.rights[t]
        if l < 0 {
            return r
        }
        if r < 0 {
            return l
        }
        let s = self.min_of(r)
        self.keys[t] = s
        let nr = self.del(r, s)
        self.rights[t] = nr
        t
    }

    fn height(self, t: int) -> int {
        if t < 0 {
            return 0
        }
        let a = self.height(self.lefts[t])
        let b = self.height(self.rights[t])
        if a > b { a + 1 } else { b + 1 }
    }

    fn collect(self, t: int, out: Vec<string>) {
        if t < 0 {
            return
        }
        self.collect(self.lefts[t], out)
        out.push("${self.keys[t]}")
        self.collect(self.rights[t], out)
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut tr = Tree { keys: [], lefts: [], rights: [], root: -1, found: false }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "insert" {
            let x = parts[1].parse::<int>().unwrap_or(0)
            if tr.contains(x) {
                println("dup")
            } else {
                tr.insert(x)
                println("ok")
            }
        } else if cmd == "contains" {
            let x = parts[1].parse::<int>().unwrap_or(0)
            if tr.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x = parts[1].parse::<int>().unwrap_or(0)
            tr.found = false
            let r = tr.del(tr.root, x)
            tr.root = r
            if tr.found { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            let mut out: Vec<string> = []
            tr.collect(tr.root, out)
            if out.len() == 0 {
                println("<empty>")
            } else {
                println(out.join(" "))
            }
        } else if cmd == "height" {
            println("${tr.height(tr.root)}")
        } else if cmd == "min" {
            if tr.root < 0 { println("empty") } else { println("${tr.min_of(tr.root)}") }
        } else if cmd == "max" {
            if tr.root < 0 {
                println("empty")
            } else {
                let mut t = tr.root
                while tr.rights[t] >= 0 {
                    t = tr.rights[t]
                }
                println("${tr.keys[t]}")
            }
        }
    }
}

